    35	  G.addWeightedEdgesFrom([
    36	    [args.a, args.b, 1.0],
    37	    [args.b, args.c, 2.0],
    38	    [args.c, args.d, 3.0],
    39	    [args.d, args.e, 4.0],
    40	    [args.a, args.e, 5.0],
    41	  ]);
    42	
    43	  pyPrint(asPyInt(G.numberOfEdges())); // 获取边数量
    44	  pyPrint(G.getEdgeData(args.a, args.b).weight); // 获取边权重
    45	  const mst = minimumSpanningTree(G); // 最小生成树
    46	  pyPrint(asPyInt(mst.numberOfEdges())); // MST边数量
